using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "QuicksandDanceAction", menuName = "Data/Battle/Battle Actions/Sothis/QuicksandDance Action")]
public class QuicksandDanceAction : GainSandsOfTimeBasedAction
{
	[Header("Chanting")]
	[SerializeField]
	private DefaultEffectAction gainChantingEffectAction;

	[SerializeField]
	private ChantingEffect chantingEffect;

	public DefaultEffectAction GainChantingEffectAction => gainChantingEffectAction;

	public override int GetSandsOfTimeAmount(int amount = 0)
	{
		return ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsEffectActiveGetAmount(chantingEffect, activateFeedback: false) + 1;
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		CastTarget(target, source);
		gainChantingEffectAction.CastTargetAmount(target, amount, source);
	}
}
